import sympy

def sum_of_divisors(n):
    return sum(sympy.divisors(n))

def is_bouncy_prime(n):
    f_n = sum_of_divisors(n)
    f_f_n = sum_of_divisors(f_n)
    return sympy.isprime(n) and sympy.isprime(f_f_n)

def smallest_bouncy_prime():
    n = 2
    while True:
        if is_bouncy_prime(n):
            return n
        n += 1

smallest_bouncy_prime = smallest_bouncy_prime()
print(smallest_bouncy_prime)
